add_filter( 'woocommerce_checkout_fields', 'perfectpixel_add_shipping_phone_field', 9999 );

function perfectpixel_add_shipping_phone_field( $fields ) {
	if ( isset( $fields['shipping'] ) && ! isset( $fields['shipping']['shipping_phone'] ) ) {
		$fields['shipping']['shipping_phone'] = array(
			'label'        => __( 'Phone', 'woocommerce' ),
			'type'         => 'tel',
			'required'     => false,
			'class'        => array( 'form-row-wide' ),
			'validate'     => array( 'phone' ),
			'autocomplete' => 'tel',
			'priority'     => 95,
		);
	}
	return $fields;
}
